import ast,copy,hashlib,json,math,pathlib,subprocess
root=pathlib.Path('/workspace')
r=json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve','run://r-001'],text=True))
p=json.loads((root/'proposal.json').read_text())
def validate(x,s,path='study'):
 typ=s.get('type')
 if typ:
  assert {'object':isinstance(x,dict),'array':isinstance(x,list),'string':isinstance(x,str),'boolean':isinstance(x,bool)}[typ],(path,typ)
 if 'enum' in s: assert x in s['enum'],path
 if 'const' in s: assert x==s['const'],path
 if isinstance(x,str): assert len(x)>=s.get('minLength',0),path
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x):validate(v,s.get('items',{}),path+'.'+str(i))
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=x.keys(),path
  if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),path
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
def mod(path):return ast.parse(path.read_text())
def model(t):return next(x for x in t.body if isinstance(x,ast.ClassDef) and x.name=='Model')
def methods(t):return {n.name:n for n in model(t).body if isinstance(n,ast.FunctionDef)}
def dump(t):return ast.dump(t,include_attributes=False)
def cfg(t):return ast.literal_eval(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
old=mod(root/'history_g2_r0018_joint_exposure.py'); om=methods(old)
base=None
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
new_keys={'residual_content_source','residual_rate_source'}
for v in p['variants']:
 assert pathlib.Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 src=(root/v['file']).read_text();compile(src,v['file'],'exec'); t=ast.parse(src)
 assert cfg(t)==v['config']
 assert {k:x for k,x in cfg(t).items() if k not in new_keys}==cfg(old)
 for n in ast.walk(t):
  if isinstance(n,ast.Import):assert all(x.name.split('.')[0] in allowed for x in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','exec','eval','compile','__import__'}
 mm=methods(t); unchanged=[]
 for name,n in om.items():
  if name not in {'__init__','_residual_features'}:assert dump(n)==dump(mm[name]),name;unchanged.append(name)
 for name in ['FeedbackMemory','JointBlock']:
  assert dump(next(n for n in old.body if isinstance(n,ast.ClassDef) and n.name==name))==dump(next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name==name))
 # Remove only the two documented post-summary replacement branches.
 f=copy.deepcopy(mm['_residual_features'])
 f.body=[n for n in f.body if not (isinstance(n,ast.If) and any(isinstance(x,ast.Attribute) and x.attr in new_keys for x in ast.walk(n.test)))]
 assert dump(f)==dump(om['_residual_features']),'archived complete-product path drift'
 init=copy.deepcopy(mm['__init__'])
 args=init.args.args; start=len(args)-len(init.args.defaults)
 defaults={args[start+i].arg:d for i,d in enumerate(init.args.defaults)}
 for key in new_keys:
  d=defaults[key];assert isinstance(d,ast.Subscript) and isinstance(d.value,ast.Name) and d.value.id=='CONFIG' and d.slice.value==key
 keep=[a for a in args if a.arg not in new_keys]
 init.args.args=keep;init.args.defaults=[defaults[a.arg] for a in keep if a.arg in defaults]
 def added(n):
  if isinstance(n,ast.If) and any(isinstance(x,ast.Name) and x.id in new_keys for x in ast.walk(n.test)):return True
  return isinstance(n,ast.Assign) and any(isinstance(a,ast.Attribute) and a.attr in new_keys for a in n.targets)
 init.body=[n for n in init.body if not added(n)]
 assert dump(init)==dump(om['__init__']),'inherited init drift'
 # Outside CONFIG every new cell is identical, including the module graph.
 nt=copy.deepcopy(t)
 for n in nt.body:
  if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets):n.value=ast.Constant(value=None)
 normalized=dump(nt)
 if base is None:base=normalized
 else:assert normalized==base,'cell source drift'
 print(v['name'],'PASS syntax, CONFIG, imports, unchanged helpers',len(unchanged),'init and archived full-path AST;',hashlib.sha256(src.encode()).hexdigest())
 # Defaults for all existing CONFIG values must evaluate consistently.
 for a,d in defaults.items():
  if a in cfg(t):
   value=cfg(t)[d.slice.value] if isinstance(d,ast.Subscript) else ast.literal_eval(d)
   assert list(value) == list(cfg(t)[a]) if isinstance(value,(tuple,list)) else value==cfg(t)[a],a
for a in p['knowledge_assessments']:
 assert {'knowledge_id','decision','rationale','transformed_mechanism','variant_names','nearest_work_difference','falsifier'}<=a.keys()
 assert a['decision'] in ['used','considered','rejected','unresolved']
 assert set(a['variant_names'])<={v['name'] for v in p['variants']}
print('PASS strict supplied study schema, evidence/protocol/parent references, variant interface and knowledge assessments')
# Independent scalar mechanism cases, no tensor execution implied.
for n,f,b,q in [(1,1,1,3),(4,.5,.5,-2),(16,.25,.25,7),(100,.1,.1,0)]:
 alpha=n/(n+4); gate=alpha*f+(1-alpha)*b
 old_moment=q*gate-q*b; centered=q*alpha*(f-b)
 assert math.isclose(old_moment,centered,abs_tol=1e-14)
 assert math.isclose(centered,0,abs_tol=1e-14)
 assert n>0 and q==q
# Distinguish product sensitivity from raw-rate information and content scaling.
n,q,b=4,2,.25;alpha=n/(n+4)
assert q*alpha*(.75-b)==.5
assert q*alpha*(.25-b)==0
assert q==2  # content replacement remains when centered product vanishes
assert [n/100]*4 == [.04]*4
print('PASS scalar attenuation, zero-product/content counterexample and repeated-count replacement checks; torch/numpy unavailable, host execution pending')
print('Expected residual width',8*(4*(8+1)+1),'added params',96*8+296*64+64+64*4+4)
PY"

